Tests:
import { describe, expect, it } from "vitest";
import { wordLengths } from "@/katas/001-map/kata";

describe("wordLengths", () => {
  it("turns an empty list into an empty list", () => {
    expect(wordLengths([])).toEqual([]);
  });

  it("measures a single word", () => {
    expect(wordLengths(["hi"])).toEqual([2]);
  });

  it("measures every word in order", () => {
    expect(wordLengths(["a", "bb", "ccc"])).toEqual([1, 2, 3]);
  });

  it("leaves the original list unchanged", () => {
    const words = ["hello", "world"];
    wordLengths(words);
    expect(words).toEqual(["hello", "world"]);
  });

  it("returns a new list rather than the original", () => {
    const words = ["a", "b"];
    const result = wordLengths(words);
    expect(result).not.toBe(words);
  });
});

